const { performance } = require('node:perf_hooks');
const { diffLines, unifiedHunks, applyHunks } = require('./src/diff');

function lcs(a, b) {
  const row = new Array(b.length + 1).fill(0);
  for (const line of a) {
    let diagonal = 0;
    for (let j = 1; j <= b.length; j++) {
      const previous = row[j];
      row[j] = line === b[j - 1] ? diagonal + 1 : Math.max(row[j], row[j - 1]);
      diagonal = previous;
    }
  }
  return row[b.length];
}

function check(a, b) {
  const originalA = a.slice();
  const originalB = b.slice();
  const script = diffLines(a, b);
  assert.deepEqual(script, diffLines(a, b));
  assert.deepEqual(script.filter(e => e.op !== 'insert').map(e => e.line), a);
  assert.deepEqual(script.filter(e => e.op !== 'delete').map(e => e.line), b);
  assert.equal(script.filter(e => e.op !== 'equal').length, a.length + b.length - 2 * lcs(a, b));
  let inserted = false;
  for (const entry of script) {
    if (entry.op === 'equal') inserted = false;
    else if (entry.op === 'insert') inserted = true;
    else assert.equal(inserted, false);
  }
  for (const context of [0, 1, 2, 3]) {
    const hunks = unifiedHunks(a, b, { context });
    const snapshot = JSON.stringify(hunks);
    for (const h of hunks) {
      const oldIndex = h.oldStart - (h.oldLines ? 1 : 0);
      const newIndex = h.newStart - (h.newLines ? 1 : 0);
      assert.deepEqual(h.lines.filter(line => line[0] !== '+').map(line => line.slice(1)), a.slice(oldIndex, oldIndex + h.oldLines));
