      assert.deepEqual(h.lines.filter(line => line[0] !== '+').map(line => line.slice(1)), a.slice(oldIndex, oldIndex + h.oldLines));
      assert.deepEqual(h.lines.filter(line => line[0] !== '-').map(line => line.slice(1)), b.slice(newIndex, newIndex + h.newLines));
    }
    assert.deepEqual(applyHunks(a, hunks), b);
    assert.equal(JSON.stringify(hunks), snapshot);
  }
  assert.deepEqual(a, originalA);
  assert.deepEqual(b, originalB);
}

test('exhaustive minimality, ordering and roundtrips on repeated and empty lines', () => {
  const arrays = [[]];
  for (let length = 1; length <= 5; length++) {
    for (let mask = 0; mask < 2 ** length; mask++) {
      arrays.push(Array.from({ length }, (_, i) => mask & (1 << i) ? 'repeat' : ''));
    }
  }
  for (const a of arrays) for (const b of arrays) check(a, b);
});

test('deterministic mixed-prefix randomized roundtrips', () => {
  let state = 123456;
  const random = n => {
    state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
    return state % n;
  };
  const pool = ['', 'repeat', '+literal', '-literal', ' literal', '\r', 'other'];
  for (let i = 0; i < 1000; i++) {
    const a = Array.from({ length: random(25) }, () => pool[random(pool.length)]);
    const b = Array.from({ length: random(25) }, () => pool[random(pool.length)]);
    check(a, b);
  }
});

test('zero-line coordinates, context limits, touching context and separated hunks', () => {
  assert.deepEqual(unifiedHunks([], ['+']), [{ oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['++'] }]);
  assert.deepEqual(unifiedHunks(['-'], []), [{ oldStart: 1, oldLines: 1, newStart: 0, newLines: 0, lines: ['--'] }]);
  assert.deepEqual(unifiedHunks(['a'], ['a', 'b'], { context: 0 }), [{ oldStart: 1, oldLines: 0, newStart: 2, newLines: 1, lines: ['+b'] }]);
  assert.deepEqual(unifiedHunks(['a', 'b'], ['a'], { context: 0 }), [{ oldStart: 2, oldLines: 1, newStart: 1, newLines: 0, lines: ['-b'] }]);
  assert.deepEqual(unifiedHunks(['a'], ['a']), []);
  const a = ['head', 'old1', 'gap1', 'gap2', 'old2', 'tail'];
  const b = ['head', 'new1', 'gap1', 'gap2', 'new2', 'tail'];
  assert.deepEqual(unifiedHunks(a, b, { context: 1 }), [{ oldStart: 1, oldLines: 6, newStart: 1, newLines: 6, lines: [' head', '-old1', '+new1', ' gap1', ' gap2', '-old2', '+new2', ' tail'] }]);
  a.splice(4, 0, 'gap3');
  b.splice(4, 0, 'gap3');
  assert.deepEqual(unifiedHunks(a, b, { context: 1 }), [
    { oldStart: 1, oldLines: 3, newStart: 1, newLines: 3, lines: [' head', '-old1', '+new1', ' gap1'] },
    { oldStart: 5, oldLines: 3, newStart: 5, newLines: 3, lines: [' gap3', '-old2', '+new2', ' tail'] },
  ]);
  assert.deepEqual(applyHunks(['a', 'b', 'c', 'd'], [
    { oldStart: 1, oldLines: 0, newStart: 2, newLines: 2, lines: ['+x', '+y'] },
    { oldStart: 3, oldLines: 1, newStart: 4, newLines: 0, lines: ['-c'] },
  ]), ['a', 'x', 'y', 'b', 'd']);
  const original = ['a'];
  const copy = applyHunks(original, []);
  assert.deepEqual(copy, original);
  assert.notEqual(copy, original);
});

test('malformed and inapplicable hunks reject with the offending index', () => {
  const a = ['a', 'b', 'c'];
  const valid = { oldStart: 2, oldLines: 1, newStart: 2, newLines: 1, lines: ['-b', '+B'] };
  const cases = [null, {}, { ...valid, lines: null }, { ...valid, lines: [42] },
    { ...valid, lines: ['?b'] }, { ...valid, lines: [''] },
    { ...valid, lines: ['-wrong', '+B'] }, { ...valid, lines: [' wrong'] },
    { ...valid, oldStart: 0 }, { ...valid, oldStart: -1 }, { ...valid, oldStart: 1.5 },
    { ...valid, oldStart: Infinity }, { ...valid, oldStart: '2' },
    { ...valid, newStart: 0 }, { ...valid, newStart: 3 },
    { ...valid, oldLines: 0 }, { ...valid, oldLines: 2 },
    { ...valid, newLines: 0 }, { ...valid, newLines: 2 },
    { ...valid, oldStart: 4, newStart: 4 },
    { oldStart: 4, oldLines: 0, newStart: 5, newLines: 1, lines: ['+x'] },
  ];
  for (const h of cases) assert.throws(() => applyHunks(a, [h]), /hunk 0 does not apply/);
  assert.throws(() => applyHunks(a, [valid, valid]), /hunk 1 does not apply/);
  assert.throws(() => applyHunks(a, [valid, { oldStart: 1, oldLines: 1, newStart: 1, newLines: 1, lines: [' a'] }]), /hunk 1 does not apply/);
  assert.throws(() => applyHunks(a, [valid, { oldStart: 3, oldLines: 1, newStart: 4, newLines: 1, lines: [' c'] }]), /hunk 1 does not apply/);
});

test('small edits to 20,000-line unique and repetitive files stay under a second', () => {
  for (const repetitive of [false, true]) {
    const a = Array.from({ length: 20000 }, (_, i) => repetitive ? 'repeat' : `line ${i}`);
    const b = a.slice();
    b.splice(100, 1, 'replacement');
    b.splice(10000, 0, '+insert');
    b.splice(19000, 1);
    const started = performance.now();
    const edits = diffLines(a, b);
    const hunks = unifiedHunks(a, b);
    const applied = applyHunks(a, hunks);
    const elapsed = performance.now() - started;
    assert.deepEqual(applied, b);
    assert.equal(edits.filter(e => e.op !== 'equal').length, 4);
    assert.ok(elapsed < 800, `elapsed ${elapsed}ms`);
    console.log(`${repetitive ? 'repetitive' : 'unique'} 20,000-line diff + hunks + apply: ${elapsed.toFixed(2)}ms`);
  }
});
